#!/usr/bin/env bash
# Creates a placeholder lib/firebase_options.dart when the real one is absent,
# so `flutter analyze`, `flutter test` and `flutter build web` work on a fresh
# clone. The real file is generated by `flutterfire configure` and is
# git-ignored (it must never be committed).
set -euo pipefail
cd "$(dirname "$0")/.."
target="lib/firebase_options.dart"
if [[ -f "$target" ]]; then
  echo "$target already exists — leaving it untouched."
  exit 0
fi
cat > "$target" <<'EOF'
// PLACEHOLDER — generated by tool/ensure_firebase_options.sh.
// Replace it by running:  flutterfire configure
// This file is git-ignored; never commit real Firebase options.
import 'package:firebase_core/firebase_core.dart';

class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform => throw UnsupportedError(
        'lib/firebase_options.dart is a placeholder. Run `flutterfire configure`.',
      );
}
EOF
echo "Wrote placeholder $target"
